    ("<li><strong>S-151</strong> — Le rug-pull et l'intégrité continue. <code>[C]</code> — Vol. I, <em>Monographie</em> §3.10.3 et §3.10.4, par Vol. III <code>H-25</code> §7.3. Verrou « ouvert en 2026 ».</li>", "<li><strong>S-151</strong> — Le rug-pull et l'intégrité continue. <code>[C]</code> — Vol. I, <em>Monographie</em> §3.10.3 et §3.10.4, par Vol. III <code>H-25</code> §7.3. Verrou « ouvert en 2026 ». <em>(Siège\xa0: ch.\xa019.)</em></li>", 'O-04_S-151'),
    ('<li><strong>S-152</strong> — Injection et empoisonnement. <code>[C]</code> — Vol. I, <em>Monographie</em> §2.10.2.1, §2.10.2.2, §3.10.3, par Vol. III <code>H-26</code> §7.3. CVE-2025-32711.</li>', '<li><strong>S-152</strong> — Injection et empoisonnement. <code>[C]</code> — Vol. I, <em>Monographie</em> §2.10.2.1, §2.10.2.2, §3.10.3, par Vol. III <code>H-26</code> §7.3. CVE-2025-32711. <em>(Siège\xa0: ch.\xa011.)</em></li>', 'O-04_S-152'),
